518		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
519		logging.Info(logCtx, "turn-start",
520			slog.String("event", event.Type.String()),
521			slog.String("session_id", event.SessionID),
