531			return fmt.Errorf("invalid %s event: %w", event.Type, err)
532		}
533	
534		// Fill model from hint file if the agent didn't provide it on this hook
535		if event.Model == "" {
536			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
