544		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
545		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
546			captureSpan.RecordError(err)
547			captureSpan.End()
548			return err
549		}
550		captureSpan.End()
551	
552		// Append prompt to prompt.txt on filesystem so it's available for
