568						logging.Warn(logCtx, "failed to write prompt.txt",
569							slog.String("error", writeErr.Error()))
570					}
571				}
572			}
573		}
574	
575		// Ensure strategy setup and initialize session
576		_, initSpan := perf.Start(ctx, "init_session")
577		if err := strategy.EnsureSetup(ctx); err != nil {
