1	package claudecode
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"path/filepath"
8		"strings"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11		"github.com/entireio/cli/cmd/entire/cli/transcript"
12		"github.com/entireio/cli/cmd/entire/cli/validation"
13	)
14	
15	// TranscriptLine is an alias to the shared transcript.Line type.
16	type TranscriptLine = transcript.Line
17	
18	// Type aliases for internal use.
19	type (
20		assistantMessage = transcript.AssistantMessage
21		toolInput        = transcript.ToolInput
22	)
23	
24	// SerializeTranscript converts transcript lines back to JSONL bytes
25	func SerializeTranscript(lines []TranscriptLine) ([]byte, error) {
26		var buf bytes.Buffer
27		for _, line := range lines {
28			data, err := json.Marshal(line)
29			if err != nil {
30				return nil, fmt.Errorf("failed to marshal line: %w", err)
31			}
32			buf.Write(data)
33			buf.WriteByte('\n')
34		}
35		return buf.Bytes(), nil
36	}
37	
38	// ExtractModifiedFiles extracts files modified by tool calls from transcript
39	func ExtractModifiedFiles(lines []TranscriptLine) []string {
40		fileSet := make(map[string]bool)
41		var files []string
42	
43		for _, line := range lines {
44			if line.Type != envelopeTypeAssistant {
45				continue
46			}
47	
48			var msg assistantMessage
49			if err := json.Unmarshal(line.Message, &msg); err != nil {
50				continue
51			}
52	
53			for _, block := range msg.Content {
54				if block.Type != "tool_use" {
55					continue
56				}
57	
58				// Check if it's a file modification tool
59				isModifyTool := false
60				for _, name := range FileModificationTools {
61					if block.Name == name {
62						isModifyTool = true
63						break
64					}
65				}
66	
67				if !isModifyTool {
68					continue
69				}
70	
71				var input toolInput
72				if err := json.Unmarshal(block.Input, &input); err != nil {
73					continue
74				}
75	
76				file := input.FilePath
77				if file == "" {
78					file = input.NotebookPath
79				}
80	
81				if file != "" && !fileSet[file] {
82					fileSet[file] = true
83					files = append(files, file)
84				}
85			}
86		}
87	
88		return files
89	}
90	
91	// TruncateAtUUID returns transcript lines up to and including the line with given UUID
92	func TruncateAtUUID(lines []TranscriptLine, uuid string) []TranscriptLine {
93		if uuid == "" {
94			return lines
95		}
96	
97		for i, line := range lines {
98			if line.UUID == uuid {
99				return lines[:i+1]
100			}
101		}
102	
103		// UUID not found, return full transcript
104		return lines
105	}
106	
107	// toolResultBlock represents a tool_result in a user message
108	type toolResultBlock struct {
109		Type      string `json:"type"`
110		ToolUseID string `json:"tool_use_id"`
111	}
112	
113	// userMessageWithToolResults represents a user message that may contain tool results
114	type userMessageWithToolResults struct {
115		Content []toolResultBlock `json:"content"`
116	}
117	
118	// FindCheckpointUUID finds the UUID of the message containing the tool_result
119	// for the given tool_use_id
120	func FindCheckpointUUID(lines []TranscriptLine, toolUseID string) (string, bool) {
121		for _, line := range lines {
122			if line.Type != "user" {
123				continue
124			}
125	
126			var msg userMessageWithToolResults
127			if err := json.Unmarshal(line.Message, &msg); err != nil {
128				continue
129			}
130	
131			for _, block := range msg.Content {
132				if block.Type == "tool_result" && block.ToolUseID == toolUseID {
133					return line.UUID, true
134				}
135			}
136		}
137		return "", false
138	}
139	
140	// CalculateTokenUsage calculates token usage from a Claude Code transcript.
141	// This is specific to Claude/Anthropic's API format where each assistant message
142	// contains a usage object with input_tokens, output_tokens, and cache tokens.
143	//
144	// Due to streaming, multiple transcript rows may share the same message.id.
145	// We deduplicate by taking the row with the highest output_tokens for each message.id.
146	func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
147		// Map from message.id to the usage with highest output_tokens
148		usageByMessageID := make(map[string]messageUsage)
149	
150		for _, line := range transcript {
151			if line.Type != envelopeTypeAssistant {
152				continue
153			}
154	
155			var msg messageWithUsage
156			if err := json.Unmarshal(line.Message, &msg); err != nil {
157				continue
158			}
159	
160			if msg.ID == "" {
161				continue
162			}
163	
164			// Keep the entry with highest output_tokens (final streaming state)
165			existing, exists := usageByMessageID[msg.ID]
166			if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
167				usageByMessageID[msg.ID] = msg.Usage
168			}
169		}
170	
171		// Sum up all unique messages
172		usage := &agent.TokenUsage{
173			APICallCount: len(usageByMessageID),
174		}
175		for _, u := range usageByMessageID {
176			usage.InputTokens += u.InputTokens
177			usage.CacheCreationTokens += u.CacheCreationInputTokens
178			usage.CacheReadTokens += u.CacheReadInputTokens
179			usage.OutputTokens += u.OutputTokens
180		}
181	
182		return usage
183	}
184	
185	// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
186	// If startLine > 0, only considers lines from startLine onwards.
187	func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
188		if path == "" {
189			return &agent.TokenUsage{}, nil
190		}
191	
192		lines, err := transcript.ParseFromFileAtLine(path, startLine)
193		if err != nil {
194			return nil, err //nolint:wrapcheck // caller adds context
195		}
196	
197		return CalculateTokenUsage(lines), nil
198	}
199	
200	// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
201	// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
202	// Returns a map of agentID -> toolUseID for all spawned agents.
203	func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
204		agentIDs := make(map[string]string)
205	
206		for _, line := range transcript {
207			if line.Type != "user" {
208				continue
209			}
210	
211			// Parse as array of content blocks (tool results)
212			var contentBlocks []struct {
213				Type      string          `json:"type"`
214				ToolUseID string          `json:"tool_use_id"`
215				Content   json.RawMessage `json:"content"`
216			}
217	
218			var msg struct {
219				Content json.RawMessage `json:"content"`
220			}
221			if err := json.Unmarshal(line.Message, &msg); err != nil {
222				continue
223			}
224	
225			if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
226				continue
227			}
228	
229			for _, block := range contentBlocks {
230				if block.Type != "tool_result" {
231					continue
232				}
233	
234				// Content can be a string or array of text blocks
235				var textContent string
236	
237				// Try as array of text blocks first
238				var textBlocks []struct {
239					Type string `json:"type"`
240					Text string `json:"text"`
241				}
242				if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
243					var textContentSb361 strings.Builder
244					for _, tb := range textBlocks {
245						if tb.Type == "text" {
246							textContentSb361.WriteString(tb.Text + "\n")
247						}
248					}
249					textContent += textContentSb361.String()
250				} else {
251					// Try as plain string
252					var str string
253					if err := json.Unmarshal(block.Content, &str); err == nil {
254						textContent = str
255					}
256				}
257	
258				// Look for agentId in the text. Drop any ID that isn't path-safe:
259				// callers build agent-<id>.jsonl from it and read that file, so this
260				// is the choke point that keeps the path inside subagentsDir,
261				// independent of extractAgentIDFromText's character handling.
262				if agentID := extractAgentIDFromText(textContent); agentID != "" && validation.ValidateAgentID(agentID) == nil {
263					agentIDs[agentID] = block.ToolUseID
264				}
265			}
266		}
267	
268		return agentIDs
269	}
270	
271	// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
272	func extractAgentIDFromText(text string) string {
273		const prefix = "agentId: "
274		idx := strings.Index(text, prefix)
275		if idx == -1 {
276			return ""
277		}
278	
279		// Extract the ID (alphanumeric characters after the prefix)
280		start := idx + len(prefix)
281		end := start
282		for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
283			text[end] >= 'A' && text[end] <= 'Z' ||
284			text[end] >= '0' && text[end] <= '9') {
285			end++
286		}
287	
288		if end > start {
289			return text[start:end]
290		}
291		return ""
292	}
293	
294	// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
295	// It parses the main transcript bytes from startLine, extracts spawned agent IDs,
296	// and calculates their token usage from transcript files in subagentsDir.
297	func (c *ClaudeCodeAgent) ExtractSkillEvents(transcriptData []byte, startLine int) ([]agent.SkillEvent, error) {
298		if len(transcriptData) == 0 {
299			return nil, nil
300		}
301	
302		sliced := transcript.SliceFromLine(transcriptData, startLine)
303		parsed, err := transcript.ParseFromBytes(sliced)
304		if err != nil {
305			return nil, fmt.Errorf("failed to parse transcript: %w", err)
306		}
307	
308		var events []agent.SkillEvent
309		for i, line := range parsed {
310			if line.Type != envelopeTypeAssistant {
311				continue
312			}
313	
314			var msg assistantMessage
315			if err := json.Unmarshal(line.Message, &msg); err != nil {
316				continue
317			}
318	
319			for _, block := range msg.Content {
320				if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
321					continue
322				}
323				var input toolInput
324				if err := json.Unmarshal(block.Input, &input); err != nil {
325					continue
326				}
327				skillName := strings.TrimSpace(input.Skill)
328				if skillName == "" {
329					continue
330				}
331	
332				native := map[string]string{"tool_name": "Skill"}
333				if block.ID != "" {
334					native["tool_use_id"] = block.ID
335				}
336				events = append(events, agent.SkillEvent{
337					ID:        claudeSkillEventID(block.ID, startLine+i),
338					EventType: agent.SkillEventTypeToolInvocation,
339					Skill: agent.SkillEventSkill{
340						Name: skillName,
341					},
342					Source: agent.SkillEventSource{
343						Agent:      string(agent.AgentNameClaudeCode),
344						Signal:     agent.SkillSignalClaudeSkillToolUse,
345						Confidence: agent.SkillConfidenceExplicit,
346					},
347					TranscriptAnchor: &agent.SkillEventTranscriptAnchor{
348						Unit:      "line",
349						Start:     startLine + i,
350						End:       startLine + i + 1,
351						EntryIDs:  nonEmptyStrings(line.UUID),
352						ToolUseID: block.ID,
353					},
354					Native: native,
355					Collapse: agent.SkillEventCollapse{
356						Target:           agent.SkillCollapseTargetToolPair,
357						Label:            "Skill: " + skillName,
358						DefaultCollapsed: true,
359					},
360				})
361			}
362		}
363		return events, nil
364	}
365	
366	func claudeSkillEventID(toolUseID string, line int) string {
367		if toolUseID != "" {
368			return "claude-skill-" + toolUseID
369		}
370		return fmt.Sprintf("claude-skill-line-%d", line)
371	}
372	
373	func nonEmptyStrings(values ...string) []string {
374		var out []string
375		for _, value := range values {
376			if value != "" {
377				out = append(out, value)
378			}
379		}
380		return out
381	}
382	
383	func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
384		if len(transcriptData) == 0 {
385			return &agent.TokenUsage{}, nil
386		}
387	
388		// Slice to the relevant portion and parse
389		sliced := transcript.SliceFromLine(transcriptData, startLine)
390		parsed, err := transcript.ParseFromBytes(sliced)
391		if err != nil {
392			return nil, fmt.Errorf("failed to parse transcript: %w", err)
393		}
394	
395		// Calculate token usage from parsed transcript
396		mainUsage := CalculateTokenUsage(parsed)
397	
398		if subagentsDir == "" {
399			return mainUsage, nil
400		}
401	
402		// Extract spawned agent IDs from the FULL transcript (startLine=0), not the
403		// sliced portion. A subagent spawned before this checkpoint's startLine can
404		// keep writing to its transcript in later turns; scanning only the slice
405		// would miss it and undercount subagent token usage (#329).
406		//
407		// PERF (considered, retained deliberately): this re-parses the full
408		// transcript in addition to the sliced parse above — two JSONL parses per
409		// call, growing with session length. A single-pass version was rejected as
410		// not worth the risk: ParseFromBytes silently drops malformed lines, so a
411		// parsed-entry index does not correspond to a raw line number and naively
412		// slicing the full parse at startLine would misattribute main-agent usage;
413		// doing it safely would mean threading raw-line numbers through the shared
414		// transcript parser used by every agent. A cheap line scan for the Task
415		// marker instead of a full parse would duplicate ExtractSpawnedAgentIDs'
416		// nested tool_result decoding. The common no-subagent case already avoids
417		// this cost entirely via the subagentsDir == "" short-circuit above.
418		fullParsed, err := transcript.ParseFromBytes(transcriptData)
419		if err != nil {
420			return nil, fmt.Errorf("failed to parse full transcript: %w", err)
421		}
422		agentIDs := ExtractSpawnedAgentIDs(fullParsed)
423	
424		// Calculate subagent token usage. This re-reads each subagent transcript from
425		// line 0 on every call, so mainUsage.SubagentTokens is a cumulative-since-
426		// session-start snapshot — see the CalculateTotalTokenUsage interface contract
427		// in cmd/entire/cli/agent for how callers must accumulate it.
428		if len(agentIDs) > 0 {
429			subagentUsage := &agent.TokenUsage{}
430			for agentID := range agentIDs {
431				agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
432				agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
433				if err != nil {
434					// Agent transcript may not exist yet or may have been cleaned up
435					continue
436				}
437				subagentUsage.InputTokens += agentUsage.InputTokens
438				subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
439				subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
440				subagentUsage.OutputTokens += agentUsage.OutputTokens
441				subagentUsage.APICallCount += agentUsage.APICallCount
442			}
443			if subagentUsage.APICallCount > 0 {
444				mainUsage.SubagentTokens = subagentUsage
445			}
446		}
447	
448		return mainUsage, nil
449	}
450	
451	// ExtractAllModifiedFiles extracts files modified by both the main agent and
452	// any subagents spawned via the Task tool. It parses the main transcript bytes from
453	// startLine, collects modified files from the main agent, then reads each
454	// subagent's transcript from subagentsDir to collect their modified files too.
455	// The result is a deduplicated list of all modified file paths.
456	func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
457		if len(transcriptData) == 0 {
458			return nil, nil
459		}
460	
461		// Slice to the relevant portion and parse
462		sliced := transcript.SliceFromLine(transcriptData, startLine)
463		parsed, err := transcript.ParseFromBytes(sliced)
464		if err != nil {
465			return nil, fmt.Errorf("failed to parse transcript: %w", err)
466		}
467	
468		// Collect modified files from main agent
469		fileSet := make(map[string]bool)
470		var files []string
471		for _, f := range ExtractModifiedFiles(parsed) {
472			if !fileSet[f] {
473				fileSet[f] = true
474				files = append(files, f)
475			}
476		}
477	
478		if subagentsDir == "" {
479			return files, nil
480		}
481	
482		// Find spawned subagents from the FULL transcript (startLine=0): a subagent
483		// spawned before this checkpoint's startLine may keep modifying files in
484		// later turns, and scanning only the slice would miss it (#329). Main-agent
485		// file extraction above stays scoped to the slice.
486		//
487		// PERF: the second full-transcript parse is retained deliberately for the
488		// same reasons documented on CalculateTotalTokenUsage above; the common
489		// no-subagent case is short-circuited by the subagentsDir == "" guard.
490		fullParsed, err := transcript.ParseFromBytes(transcriptData)
491		if err != nil {
492			return nil, fmt.Errorf("failed to parse full transcript: %w", err)
493		}
494		agentIDs := ExtractSpawnedAgentIDs(fullParsed)
495		for agentID := range agentIDs {
496			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
497			agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
498			if agentErr != nil {
499				// Subagent transcript may not exist yet or may have been cleaned up
500				continue
501			}
502			for _, f := range ExtractModifiedFiles(agentLines) {
503				if !fileSet[f] {
504					fileSet[f] = true
505					files = append(files, f)
506				}
507			}
508		}
509	
510		return files, nil
511	}
