	t.Parallel()
	model, err := (&ClaudeCodeAgent{}).ExtractModel(nil)
	if err != nil {
		t.Fatalf("ExtractModel returned error: %v", err)
	}
	if model != "" {
		t.Errorf("expected empty model for empty transcript, got %q", model)
	}
}

