			`{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"t%d","content":%q}]}}`+"\n",
			i, filler)
	}
	return []byte(b.String())
}

func benchExtractModel(b *testing.B, n, contentBytes int) {
	data := buildLargeTranscript(n, contentBytes)
	b.ReportAllocs()
	b.SetBytes(int64(len(data)))
	ag := &ClaudeCodeAgent{}
	for b.Loop() {
		if _, err := ag.ExtractModel(data); err != nil {
			b.Fatal(err)
		}
	}
}

// Small: ~200 turns, 500B content each (~0.2MB).
func BenchmarkExtractModel_Small(b *testing.B) { benchExtractModel(b, 200, 500) }

// Medium: ~1000 turns, 2KB content each (~4MB).
func BenchmarkExtractModel_Medium(b *testing.B) { benchExtractModel(b, 1000, 2000) }

// Large: ~2000 turns, 10KB content each (~40MB, near the 50MB blob cap).
func BenchmarkExtractModel_Large(b *testing.B) { benchExtractModel(b, 2000, 10000) }

// Baseline: the existing full-parse token calc on the same large input, for
// comparison — condensation already runs this (and more) on every commit.
func BenchmarkCalculateTokenUsage_Large(b *testing.B) {
	data := buildLargeTranscript(2000, 10000)
	b.ReportAllocs()
	b.SetBytes(int64(len(data)))
	ag := &ClaudeCodeAgent{}
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		if _, err := ag.CalculateTotalTokenUsage(data, 0, ""); err != nil {
			b.Fatal(err)
		}
	}
}

